@@ -0,0 +1,96 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, readFileSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { createApp } from "../src/http/server.js";
+import { openStore } from "../src/db/store.js";
+import { migrate } from "../src/db/migrations.js";
+import { fresh, NOW } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer ${role}-key` });
+
+test("keys are required and permissions precede routing", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const authorization of [undefined, "Bearer unknown", "Basic manager-key", "Bearer "]) {
+    const response = await handle({ path: "/items", headers: { authorization } });
+    assert.equal(response.status, 401);
+    assert.equal(response.body.error.code, "unauthorized");
+    assert.equal(typeof response.body.error.message, "string");
+  }
+  for (const role of ["viewer", "cook", "manager"]) {
+    assert.equal((await handle({ path: "/items", headers: headers(role) })).status, 200);
+    assert.equal((await handle({ path: "/audit", headers: headers(role) })).status, role === "manager" ? 200 : 403);
+  }
+  for (const role of ["viewer", "cook"]) {
+    const before = structuredClone(store.data);
+    const response = await handle({ method: "POST", path: "/orders", headers: headers(role), body: {} });
+    assert.equal(response.status, 403);
+    assert.equal(response.body.error.code, "forbidden");
+    assert.deepEqual(store.data, before);
+  }
+});
+
+test("cooks can perform only the four kitchen write operations", async () => {
+  const store = fresh();
+  const handle = createApp(store, { clock: () => NOW });
+  const request = (path, body, role = "cook") => handle({ method: "POST", path, body, headers: headers(role) });
+  const take = await request("/stocktakes", { location: "dry" }, "manager");
+  assert.equal(take.status, 201);
+  const batch = store.data.batches.find((b) => b.location === "dry");
+  const operations = [
+    ["/recipes/1/cook", { portions: 1 }],
+    [`/batches/${batch.id}/waste`, { qty: 0.1 }],
+    ["/temperatures", { location: "fridge", celsius: 4 }],
+    [`/stocktakes/${take.body.id}/counts`, { batchId: batch.id, counted: batch.qty }],
+  ];
+  for (const [path, body] of operations) {
+    assert.equal((await request(path, body, "viewer")).status, 403);
+    const response = await request(path, body);
+    assert.ok(response.status >= 200 && response.status < 300, JSON.stringify(response));
+  }
+  assert.equal((await request("/stocktakes", { location: "dry" })).status, 403);
+  assert.equal((await request(`/stocktakes/${take.body.id}/finish`, {})).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", body: { allergens: [] }, headers: headers("cook") })).status, 403);
+});
+
+test("writes and their audit entries persist once and list newest first", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-audit-"));
+  try {
+    const store = fresh();
+    store.file = join(dir, "db.json");
+    let saves = 0;
+    const save = store.save.bind(store);
+    store.save = () => { saves++; save(); };
+    const handle = createApp(store, { clock: () => NOW });
+    for (const portions of [1, 2]) {
+      assert.equal((await handle({ method: "POST", path: `/recipes/1/cook?portions=${portions}`, body: { portions }, headers: headers("cook") })).status, 200);
+    }
+    assert.equal(saves, 2);
+    const persisted = openStore(store.file);
+    assert.deepEqual(persisted.data, store.data);
+    const response = await handle({ path: "/audit", headers: headers("manager") });
+    assert.deepEqual(response.body, [...store.data.audit].reverse());
+    assert.deepEqual(response.body[0], { time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: "/recipes/1/cook?portions=2", status: 200 });
+    await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 100000 }, headers: headers("cook") });
+    assert.equal(store.data.audit.length, 2);
+    assert.equal(saves, 2);
+    assert.equal(JSON.parse(readFileSync(store.file)).audit.length, 2);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+test("schema 2 migration defaults access lists and preserves existing records", () => {
+  const old = fresh().data;
+  old.schemaVersion = 2;
+  delete old.apiKeys;
+  delete old.audit;
+  assert.deepEqual(migrate(old).apiKeys, []);
+  assert.deepEqual(migrate(old).audit, []);
+  old.apiKeys = [{ key: "custom", name: "Custom", role: "manager" }];
+  old.audit = [{ time: "2026-01-01T00:00:00.000Z" }];
+  assert.deepEqual(migrate(old).apiKeys, old.apiKeys);
+  assert.deepEqual(migrate(old).audit, old.audit);
+});
